// ---- water_body_module ---------------------------------------------------------
inline water_body watbod_add(const water_body& wbod1, const water_body& wbod2) {
    water_body wbod3;
    wbod3.area_ha = wbod1.area_ha + wbod2.area_ha;
    wbod3.precip = wbod1.precip + wbod2.precip;
    wbod3.evap = wbod1.evap + wbod2.evap;
    wbod3.seep = wbod1.seep + wbod2.seep;
    return wbod3;
}
inline water_body operator+(const water_body& wbod1, const water_body& wbod2) { return watbod_add(wbod1, wbod2); }

inline water_body watbod_div(const water_body& wbod1, float k) {
    water_body wbod2;
    wbod2.area_ha = wbod1.area_ha / k;
    wbod2.precip = wbod1.precip / k;
    wbod2.evap = wbod1.evap / k;
    wbod2.seep = wbod1.seep / k;
    return wbod2;
}
inline water_body operator/(const water_body& wbod1, float k) { return watbod_div(wbod1, k); }

inline water_body watbod_ave(const water_body& wbod1, float k) {
    water_body wbod2;
    wbod2.area_ha = wbod1.area_ha / k;
    wbod2.precip = wbod1.precip;
    wbod2.evap = wbod1.evap;
    wbod2.seep = wbod1.seep;
    return wbod2;
}
inline water_body ave(const water_body& wbod1, float k) { return watbod_ave(wbod1, k); }

